window.STORY_CHAPTERS["c0deb8dbdd12b8aeb"]={"id":"c0deb8dbdd12b8aeb","lines":[{"uid":"talk.vc.home_day_agil_12#originalText","id":"talk.vc.home_day_agil_12","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你问我怎么都没客人？只是刚好现在没有而已！","en":"You're saying I never have customers? No, no, the shop just happens to be empty right now!","ja":"客がいないだと?今、たまたまいないだけだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_agil_13#originalText","id":"talk.vc.home_day_agil_13","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"假日是生意最好的时候，所以我不太能玩游戏。","en":"Weekends are my bread and butter at the bar, so I don't have much time for gaming then.","ja":"休みはかきいれ時なんでなあんまりゲームには参加できん"},"kind":"dialogue"},{"uid":"talk.vc.home_day_agil_14#originalText","id":"talk.vc.home_day_agil_14","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"这么晚了还肯来，我是很感激……要是你真的是来当客人的话啦。","en":"I'm grateful to see you here, even this late. As long as you're here as a customer, that is.","ja":"こんな時間でも来てくれるのはありがたい……お前がちゃんと客だったらな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_11#originalText","id":"talk.vc.home_day_alice_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天开始要再次认真工作。……我也会陪着你的。","en":"Starting today, you need to seriously get back to your work. Don't worry...I'll be here for you.","ja":"また今日からしっかり働きなさい……私も、一緒ですから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_12#originalText","id":"talk.vc.home_day_alice_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"看着认真生活的人们，想要守护他们的心情就会变得更加强烈。","en":"When I see the people, living their daily lives, I feel a very strong urge to protect them.","ja":"日々生活を送る人たちを見ていると、守りたいという気持ちが強くなります"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_13#originalText","id":"talk.vc.home_day_alice_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"安息日啊……那么，我们和《雨缘》一起到某处走走吧。","en":"A day of rest? Well then, let us go somewhere with Amayori.","ja":"安息日ですか……では、《雨縁》と共にどこかに行きましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_14#originalText","id":"talk.vc.home_day_alice_14","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"好好养精蓄锐了一番呢。你我都要加油喔。","en":"You have more vigor now, I see. Let's both have a productive week.","ja":"英気を養えましたねお互い、またがんばりましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_child_11#originalText","id":"talk.vc.home_day_alice_child_11","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天开始继续努力吧。记得期待我带的午餐喔！","en":"It's back to work tomorrow! I hope you like the lunch I'm packing you.","ja":"また今日から頑張りましょうお昼、楽しみにしててね! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_child_12#originalText","id":"talk.vc.home_day_alice_child_12","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"工作顺利吗？我这边做得很愉快喔。","en":"How is your work coming along? I'm rather enjoying mine.","ja":"お仕事の方はどう? 私は、けっこう楽しいわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_child_13#originalText","id":"talk.vc.home_day_alice_child_13","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"安息日啊，那就大家一起玩吧。","en":"Let's all go out somewhere together on the day of rest.","ja":"安息日は、みんな一緒に遊びましょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_alice_child_14#originalText","id":"talk.vc.home_day_alice_child_14","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天玩得很开心呢。感觉到下个安息日之前，我又能努力加油了。","en":"Today's day of rest was lots of fun! Now I feel energized for the rest of the week.","ja":"今日は楽しかったわこれで、また次の安息日まで頑張れそう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_argo_11#originalText","id":"talk.vc.home_day_argo_11","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你正要开始工作吗？我今天休假唷。","en":"Are you going to work right now? I've got the day off.","ja":"そっちはこれから仕事カ?オレっちは今日はお休みダヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_argo_12#originalText","id":"talk.vc.home_day_argo_12","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"情报商人工作不分日子的。毕竟不知道能在何时何地捡到情报嘛。","en":"Days of the week have no meaning for an informant. You never know when some juicy intel will show up.","ja":"情報屋に曜日は関係ないヨいつどこで情報が拾えるかわからないからネ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_argo_13#originalText","id":"talk.vc.home_day_argo_13","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"嗯，就今天，找个地方玩一玩或许也不错……","en":"Well, a day of fun might be called for...","ja":"まあ、今日くらいはどこかで遊んでもいいかもナ……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_argo_14#originalText","id":"talk.vc.home_day_argo_14","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你一脸疲惫呢，是不是玩过头啦？","en":"You look tired, man. Are you partying too hard?","ja":"なんか疲れた顔をしているナ遊びすぎじゃないノカ?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_11#originalText","id":"talk.vc.home_day_asuna_11","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"从今天起的这个礼拜，再一起好好努力吧。","en":"Another week starts today. Let's crush it together again!","ja":"今日から一週間また一緒に頑張りましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_12#originalText","id":"talk.vc.home_day_asuna_12","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"平日不太能跟你见面，所以反过来说，一点点的见面时光就让人很开心。","en":"I'm sad that I don't get to see you much on weekdays, but I'm grateful for every minute.","ja":"平日はなかなか会えないけどその分ちょっと会える時間がうれしいの"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_13#originalText","id":"talk.vc.home_day_asuna_13","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"如果可以，假日我想和你一直在一起呢。","en":"I wish I could spend my entire day off with you.","ja":"おやすみの日は、できればずーっと一緒にいたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_asuna_14#originalText","id":"talk.vc.home_day_asuna_14","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我今天很开心，谢谢你。","en":"Thanks again. I had a lot of fun today.","ja":"今日、とっても楽しかったねありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_bercouli_11#originalText","id":"talk.vc.home_day_bercouli_11","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"嗯？有什么关系嘛，把今天也当作安息日就好啦。","en":"Hm? I don't see the problem. We'll just call this another day of rest.","ja":"ん?いいんじゃないか今日も安息日ってことにしようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_bercouli_12#originalText","id":"talk.vc.home_day_bercouli_12","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"姑且还是要做点事，不然就没办法大摇大摆地休息啦！","en":"You'd better get in a good day's work, otherwise I won't let your arrogant ass have a rest tomorrow!","ja":"一応、働いておかないとでかい顔して休めないからな!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_bercouli_13#originalText","id":"talk.vc.home_day_bercouli_13","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"安息日就好好休息吧。","en":"Come on, it's a day of rest. Rest.","ja":"安息日くらい、ゆっくり休もうぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_bercouli_14#originalText","id":"talk.vc.home_day_bercouli_14","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"今天很开心啊。明天开始再请你多多指教啦。","en":"Today was rather enjoyable. Let's do it again tomorrow.","ja":"今日はなかなか楽しかったぜ明日からもよろしくな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_cardinal_11#originalText","id":"talk.vc.home_day_cardinal_11","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"安息日结束，世界又将开始转动。","en":"The day of rest has ended, and the world is back on the move.","ja":"安息日が終わり、また世界が動き出したな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_cardinal_12#originalText","id":"talk.vc.home_day_cardinal_12","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我喜欢这个世界的人们辛勤工作的样子……因为大家都坚强而拼尽全力地活着。","en":"I like how the people of this world work. They live healthy, earnest lives.","ja":"わしはこの世界の人間の営みが好きじゃ……みな、健気に必死に生きておるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_cardinal_13#originalText","id":"talk.vc.home_day_cardinal_13","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我也很期待安息日喔。因为观察对象的行动，也会跟平常不一样。","en":"I, too, enjoy days of rest. The actions of those I'm observing change.","ja":"安息日はわしも楽しみにしているぞ観察対象の行動も、普段とは変わるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_cardinal_14#originalText","id":"talk.vc.home_day_cardinal_14","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"一个礼拜居然只有一次安息日，外面世界的人还真是勤奋呢……","en":"Only one day of rest per week? Humans on the outside certainly work hard.","ja":"週に一度しか安息日がないとは外の世界の人間というのはよほど働き者なのだな……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_deusolbert_11#originalText","id":"talk.vc.home_day_deusolbert_11","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"那么，今天也来护卫人界吧","en":"Now then. Guarding the Human Empire today again.","ja":"さて、今日もまた人界の警護にあたるか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_deusolbert_12#originalText","id":"talk.vc.home_day_deusolbert_12","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"就目前所见，人界没有异常。和平是再好不过。","en":"There are no abnormalities in the Human Realm at present. I am grateful for the peace.","ja":"今のところ、人界に異常なしだ平和が何よりだな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_deusolbert_13#originalText","id":"talk.vc.home_day_deusolbert_13","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"像你们这样的人类，安息日最好还是休息吧。","en":"Humans such as yourself should rest up on your day of rest.","ja":"お前たちのような人間は安息日は休んだほうがいいだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_deusolbert_14#originalText","id":"talk.vc.home_day_deusolbert_14","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"对我们集成骑士而言，是不是安息日都无关紧要。","en":"To us Integrity Knights, days of rest have no meaning.","ja":"我ら整合騎士にとっては安息日かそうでないかなど関係のないことだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_11#originalText","id":"talk.vc.home_day_edith_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天起又要前往任务地点了。我会寂寞的，可以握一下我的手吗？","en":"I'll be returning to my post, starting today. I'm feeling lonely. Can I hold your hand?","ja":"今日からまた任地に向かうの寂しいから、ちょっと手を握ってもいい? "},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_12#originalText","id":"talk.vc.home_day_edith_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"又要巡逻、又要侦查的，别看我这样，我其实很忙啊。","en":"I may not look it, but I'm rather busy. What with spying and patrolling, and all.","ja":"見回りしたり、偵察に行ったりこう見えても割と忙しいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_13#originalText","id":"talk.vc.home_day_edith_13","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"终于放假啦。就算是集成骑士，会累就是会累啊。","en":"Finally, a day off! Even Integrity Knights get exhausted.","ja":"やっとお休みだね整合騎士でも、疲れるものは疲れるのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_edith_14#originalText","id":"talk.vc.home_day_edith_14","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"假日消除了不少疲劳，我应该又能加油啦。","en":"This day of rest truly rejuvenated me. I'm ready to face another week.","ja":"休みでずいぶん疲れがとれた。また頑張れそうかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eldrie_11#originalText","id":"talk.vc.home_day_eldrie_11","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"若有统领地，我自然愿意粉身碎骨地工作。但实在没有能工作之处……","en":"If at a controlled site, I naturally strive to work hard, but there is no impetus to work...","ja":"統括地でもあれば、無論粉骨砕身の心持ちで働きますが今はただ命を待つ身です……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eldrie_12#originalText","id":"talk.vc.home_day_eldrie_12","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"庸庸碌碌地工作不符合我的个性。在需要我的力量之刻到来前，就悠闲地养精蓄锐吧。","en":"Merely working hard is not my style. I would rather reserve my energy for when my skill is actually needed.","ja":"あくせく働くのは性に合いませぬ私の力が必要な時までじっと力を溜めておくとしましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eldrie_13#originalText","id":"talk.vc.home_day_eldrie_13","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"安息日……这样啊，市井小民每天都在工作啊。","en":"It is a day of rest? I see. So, citizens work every day.","ja":"安息日……そうですか市井の民は、毎日働いているのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eldrie_14#originalText","id":"talk.vc.home_day_eldrie_14","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"今天真是充实的一天。您如果愿意，下个安息日我也会相随。","en":"It was a rather fulfilling day. I would love to spend my next day of rest with you.","ja":"なかなか充実した一日でした次の安息日も、よろしければご一緒に"},"kind":"dialogue"},{"uid":"talk.vc.home_day_entokia_integrator_11#originalText","id":"talk.vc.home_day_entokia_integrator_11","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"今天开始又要运行任务了，我们好好干吧！","en":"Back on duty today. Let's put in a good day's work!","ja":"今日からまた任務ですなしっかり働きましょ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_entokia_integrator_12#originalText","id":"talk.vc.home_day_entokia_integrator_12","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"大家都很生气喔，说你不知不觉就闹失踪。呵呵呵，老师也很调皮耶。","en":"Everyone was really angry that you suddenly went missing. Haha, even you play hooky, Master?","ja":"みんな怒ってましたよいつの間にかいなくなったってくくく、先生もやんちゃっすね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_entokia_integrator_13#originalText","id":"talk.vc.home_day_entokia_integrator_13","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"今天可以放假吗？那么，我就久违地骑磐拍到远方逛逛吧。","en":"Can I really take the day off?! In that case, I'll take Iwahaku out for a ride. It's been a while.","ja":"今日はお休みでいいんですか?それじゃ、久しぶりに磐拍で遠乗りしてきますわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_entokia_integrator_14#originalText","id":"talk.vc.home_day_entokia_integrator_14","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"不用值勤的夜晚总是莫名安静，有时反而叫人睡不好觉。","en":"Nights on days off are strangely quiet, don't you think? Sometimes it's even harder to sleep.","ja":"休みの夜っつうのは、妙に静かですよね逆に眠れんこともあります"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_11#originalText","id":"talk.vc.home_day_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"安息日的隔天，确实会让人有些痛苦呢。","en":"The day after a day of rest is always tough.","ja":"安息日の次の日は確かにちょっと辛いよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_12#originalText","id":"talk.vc.home_day_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"跟挥斧伐木的时候相比，这里的生活确实让人快乐多了呢。","en":"Life is so much more fun now, compared to my days of axe-swinging.","ja":"木に斧を振ってた頃に比べれば楽しくて仕方がないよここの生活は"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_13#originalText","id":"talk.vc.home_day_eugeo_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"难得的安息日，一起去街上买东西吧。","en":"Since it's a day of rest, we should go out shopping or something!","ja":"せっかくの安息日だし街に買い物にでも行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_14#originalText","id":"talk.vc.home_day_eugeo_14","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我今天也很开心喔，谢谢你。","en":"Thanks again. I had a lot of fun today!","ja":"今日も楽しかったよありがとう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_child_11#originalText","id":"talk.vc.home_day_eugeo_child_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好，这礼拜也要比赛看谁能发出比较多清亮的声音。","en":"Okay, here's the challenge this week: Which one of us makes the better sounds?","ja":"よーし、今週もどっちがいい音出せるか、勝負だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_child_12#originalText","id":"talk.vc.home_day_eugeo_child_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我懂你想要偷懒的心情，但还是要好好工作啊。","en":"I can understand why you want to slack off, but you need to be dedicated to your job.","ja":"サボりたくなる気持ちもわかるけど仕事はしっかりしないとダメだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_child_13#originalText","id":"talk.vc.home_day_eugeo_child_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"难得的安息日，一起出门走走吧。","en":"Since it's a day of rest, want to go out somewhere?","ja":"せっかくの安息日だからどこかに出かけようか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_eugeo_child_14#originalText","id":"talk.vc.home_day_eugeo_child_14","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天的安息日很开心呢。真期待下周的安息日。","en":"Today's day of rest was lots of fun! I can't wait until next week's!","ja":"今日の安息日は楽しかったねまた来週が楽しみだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fanatio_11#originalText","id":"talk.vc.home_day_fanatio_11","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"那么，从今天开始，将再次着手任务。","en":"Well. Back to work.","ja":"それでは、本日よりまた任務に当たります"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fanatio_12#originalText","id":"talk.vc.home_day_fanatio_12","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"有报告指出，在各地发现暗之势力……必须要加以应对呢。","en":"Dark forces have been spotted nearby. I must do something about it.","ja":"各地で闇の勢力を見かけたという報告が……対処が必要ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fanatio_13#originalText","id":"talk.vc.home_day_fanatio_13","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"就算在安息日，也还是不能放松。","en":"Even on days of rest, we must remain vigilant.","ja":"安息日と言えど、気を抜くわけには参りません"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fanatio_14#originalText","id":"talk.vc.home_day_fanatio_14","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"安息日过的还充实吗？那就好。","en":"Was your day of rest meaningful? Glad to hear it.","ja":"有意義な安息日になりましたか?ならばよかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fizel_11#originalText","id":"talk.vc.home_day_fizel_11","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"啊～啊～又要念书了吗。要是可以骑飞龙就好了。","en":"Oh dear. Studying again? I wish I could go flying on a dragon.","ja":"あーあ、またお勉強かあ飛竜とかに乗れたらいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fizel_12#originalText","id":"talk.vc.home_day_fizel_12","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我有好好念书啦。真的啦，是真的！","en":"But I really am studying! I swear!","ja":"ちゃんと勉強してるわよほんとよ、ほんと!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fizel_13#originalText","id":"talk.vc.home_day_fizel_13","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"终于到安息日了！希望今天可以出去玩。","en":"Finally, a day of rest! I hope I can go out today.","ja":"やっと安息日!今日はお出かけできるといいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_fizel_14#originalText","id":"talk.vc.home_day_fizel_14","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"安息日已经要结束了……所以我还醒着。","en":"The day of rest is ending! I don't want to go to bed just yet.","ja":"もう安息日が終わっちゃう……だからまだ起きてる"},"kind":"dialogue"},{"uid":"talk.vc.home_day_iskahn_11#originalText","id":"talk.vc.home_day_iskahn_11","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"这个星期做什么锻炼好呢……你有没有什么有趣的想法呀？","en":"I wonder what kind of training I should do this week... You. Any good ideas?","ja":"今週は、どんな鍛錬がいいかな……お前、何か面白い考えはないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_iskahn_12#originalText","id":"talk.vc.home_day_iskahn_12","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"好！训练很顺利！这样的话，就算人界军还是暗黑骑士，也无法超越我了！","en":"Looks like practice is coming along! At this pace, not even a Human Soldier nor Dark Knight will be able to stand in your way!","ja":"よし、訓練は順調だな!これなら人界軍にも、暗黒騎士にも後れを取ることはねえ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_iskahn_13#originalText","id":"talk.vc.home_day_iskahn_13","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"安息日？那种东西跟我无关，每天都要锻炼，每天都是战场！","en":"Day of rest? That has no meaning here. Everyday is for training. Everyday is a battlefield!","ja":"安息日?んなモンは関係ない毎日が鍛錬、毎日が戦場だ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_iskahn_14#originalText","id":"talk.vc.home_day_iskahn_14","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"要想想下星期的训练课程才行。下次，来增加一下运动量吧……","en":"I have to figure out what next weeks training course will be. Maybe for the next course I should add a little more weight...","ja":"来週の訓練課程を考えないとな次は、もうちょい負荷を大きくしてみるか……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_11#originalText","id":"talk.vc.home_day_kirito_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"周末过得很愉快呢！好，这周也要加油喔！ ","en":"That was a great weekend! Okay. Let's crush it this week! ","ja":"いい週末だったな!よし、今週も頑張ろう! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_12#originalText","id":"talk.vc.home_day_kirito_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我快等不及周末了……","en":"Is it Saturday yet?","ja":"週末が待ち遠しいな……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_13#originalText","id":"talk.vc.home_day_kirito_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要不要一起出门呢？","en":"Wanna go out someplace?","ja":"一緒に出かけないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_14#originalText","id":"talk.vc.home_day_kirito_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"假期一结束，脑中就会突然浮现很多想做的事，对吧？","en":"Man, doesn't it suck that the day after vacation,you suddenly get all sorts of ideas for things you want to do?","ja":"休みが終わった途端にやりたいことが色々浮かんでくるんだよなぁ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_child_11#originalText","id":"talk.vc.home_day_kirito_child_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天又要开始工作了。我已经等不及下一次安息日了。","en":"Back to work again today, huh. The next day of rest can't come soon enough.","ja":"今日からまた仕事だなあ次の安息日が待ち遠しいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_child_12#originalText","id":"talk.vc.home_day_kirito_child_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我这个礼拜状况超好的！昨天啊，居然还让基家斯西达的数字少了3呢！","en":"You're doing really good today! You made the Gigas Cedar's life go down three whole points!","ja":"俺、今週は調子いいぜ! 昨日はギガスシダーの天命を3も減らしたんだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_child_13#originalText","id":"talk.vc.home_day_kirito_child_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你这次的安息日有要去哪里吗？一起去采马利果的果实吧！","en":"Do you wanna go somewhere on our next day of rest? How about we go marigot picking?","ja":"今回の安息日はどこに行く? マリゴの実でも取りに行くか! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_kirito_child_14#originalText","id":"talk.vc.home_day_kirito_child_14","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"安息日终于还是结束了。再从明天开始加油吧。","en":"Aw, our day of rest is over. Back to the grind tomorrow.","ja":"安息日も終わっちゃったなまた明日から頑張ろうぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_klein_11#originalText","id":"talk.vc.home_day_klein_11","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"又是星期一啊，周末过后实在是提不起干劲耶。","en":"Monday already? It's always so hard to have energy right after a weekend.","ja":"また月曜日か週末の後ってのはどうもやる気が出ねぇなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_klein_12#originalText","id":"talk.vc.home_day_klein_12","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"总觉得，我们正在为了放假而努力呢。","en":"I feel like I'm just going through the motions until the weekend gets here.","ja":"なんだか、休みのために頑張ってるって感じだな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_klein_13#originalText","id":"talk.vc.home_day_klein_13","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"终于放假了！好啦，去喝一杯吧？","en":"Finally, a break! Wanna go out for a drink?","ja":"やっと休みだ!さて、飲みにでも行くか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_klein_14#originalText","id":"talk.vc.home_day_klein_14","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"虽然不赶快睡会出事，但又觉得睡了可惜啊……","en":"We should really turn in early, but I don't wanna waste the night either.","ja":"早く寝ないとまずいんだが寝るのはもったいないなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kureha_11#originalText","id":"talk.vc.home_day_kureha_11","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"星期一好讨厌喔……如果可以一直待在那边的世界就好了。","en":"Mondays are generally gloomy.. I would be great if we could stay in this world forever...","ja":"月曜日って気が重いわ……ずっとこっちの世界にいられたらいいのになあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kureha_12#originalText","id":"talk.vc.home_day_kureha_12","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"如果大喊：周末快来啊－－！周末会不会快一点来呢？","en":"I wonder if we scream out for the weekend to come faster, will it really happen?","ja":"早く週末になってよー!って叫んだら、本当に週末がやってこないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kureha_13#originalText","id":"talk.vc.home_day_kureha_13","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"盼望已久的周末到啰！来吧，我们今天要去哪里打猎呢？还是要去战斗？","en":"The long awaited weekend is here! Where should we go hunting today? Or should we go do a battle?","ja":"待ちに待った週末だよ!さあ、今日はどこに狩りに行く?それともバトルかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_kureha_14#originalText","id":"talk.vc.home_day_kureha_14","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"快乐的时间稍纵即逝……已经等不及下个周末了。","en":"Time sure does fly by when you're having fun... I'm already looking forward to next week.","ja":"楽しい時間はあっという間……もう次の週末が待ち遠しいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_11#originalText","id":"talk.vc.home_day_leafa_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"虽然星期一总是让人觉得辛苦，但心情忧郁就会更难过，所以我才决定要打起精神！","en":"Mondays suck, but complaining only makes it worse. So, I always try to stay positive!","ja":"月曜日は大変だけど憂鬱だって思うと余計辛いから元気出すことにしてるの! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_12#originalText","id":"talk.vc.home_day_leafa_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我已经习惯晨练了。尝试后反而会觉得很有趣喔！","en":"I'm used to morning practice by now. Wanna try it? It's actually kinda fun.","ja":"朝練は、もう慣れちゃったからやってみると、案外楽しいよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_13#originalText","id":"talk.vc.home_day_leafa_13","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"难得放假，我想跟你一起度过。","en":"Since we have some time off for once, I'd like to spend it together.","ja":"せっかくのお休みだし一緒に過ごしたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_14#originalText","id":"talk.vc.home_day_leafa_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"假期结束了。快乐的时间总是过得特别快呢。","en":"Vacation is over already? Man, time does fly when you're having fun!","ja":"お休み終わっちゃった楽しい時間は、あっという間だね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_linel_11#originalText","id":"talk.vc.home_day_linel_11","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"安息日结束后，就会觉得很寂寞……","en":"Whenever a day of rest ends, I feel rather gloomy.","ja":"安息日が終わっちゃうとなんだか寂しいです……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_linel_12#originalText","id":"talk.vc.home_day_linel_12","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"今天学了禁忌目录。可是我早就全部背起来了……","en":"I studied the Taboo Index today. Though I've already memorized the whole thing.","ja":"今日は禁忌目録の勉強をしましたもう全部覚えちゃってますけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_linel_13#originalText","id":"talk.vc.home_day_linel_13","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"今天是安息日呢。我今天想好好休息。","en":"Today is a day of rest! I would love to take it nice and slow.","ja":"安息日ですね今日はゆっくりお休みしたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_linel_14#originalText","id":"talk.vc.home_day_linel_14","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"呵呵，真是快乐的安息日呢。","en":"Hehe. What a fun day of rest that was.","ja":"ふふ、楽しい安息日でしたね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_11#originalText","id":"talk.vc.home_day_lisbeth_11","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"唉～今天开始又得多加油了，在不勉强的前提下。","en":"Aaargh. Back to the grind again. Don't over do it though, okay?","ja":"あーあ、今日からまたがんばらないとね無理しない程度に"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_12#originalText","id":"talk.vc.home_day_lisbeth_12","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"平日果然很忙啊……虽然太闲也是个问题啦。","en":"Weekdays sure are stressful, huh? Then again, when I have time off, I get bored.","ja":"やっぱり平日は忙しいなあ……ま、ヒマすぎるのも問題だけど"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_13#originalText","id":"talk.vc.home_day_lisbeth_13","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然想悠闲地度过周末，但总是会有事情要做呢。","en":"As much as I'd love to take it easy on weekends, I always wind up doing a bunch of stuff.","ja":"週末はゆっくりしたいけどなんだかんだとやることがあるのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_14#originalText","id":"talk.vc.home_day_lisbeth_14","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"在星期日的深夜，总会觉得就这样睡了很可惜对吧。","en":"Going to bed early on Sundays always feels like a missed opportunity to me.","ja":"日曜の深夜って、なんか寝るのがもったいないわよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mary_11#originalText","id":"talk.vc.home_day_mary_11","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天开始，又得认真努力才行！","en":"Back to work today. Let's be productive!","ja":"今日からまた、一生懸命頑張らないとね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mary_12#originalText","id":"talk.vc.home_day_mary_12","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我很希望自己能跟大家一样工作……所以正在学针线活之类的手工艺喔。","en":"I hope to contribute to the world as much as everyone else. That's why I sew and study.","ja":"わたしも、みんなと同じくらい働けたらいいなって思って……お裁縫とか、勉強してるの"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mary_13#originalText","id":"talk.vc.home_day_mary_13","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"安息日就稍微奢侈一点吧，我有买到便宜的鱼喔！","en":"I wanted to splurge a little since it's a Day of Rest, so I bought some fish that were on sale!","ja":"安息日は、ちょっとだけ贅沢しちゃおうかお魚、安く買えたの!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_mary_14#originalText","id":"talk.vc.home_day_mary_14","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"安息日可以跟姊姊在一起，人家真的好开心喔！嘿嘿，晚安。","en":"I'm so happy we got to spend our Day of Rest together! Hehehe. Well, goodnight.","ja":"安息日に一緒にいられてわたしすごく楽しかったよ!えへへ、おやすみなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_day_medina_11#originalText","id":"talk.vc.home_day_medina_11","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"新的一周开始了。我一定会在这周超越你。做好觉悟吧！","en":"It's the start of a new week. This is the week that I'll overtake you. You better be ready!","ja":"新たな週の始まりだ今週こそ、お前を追い抜いてやる覚悟しておけ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_medina_12#originalText","id":"talk.vc.home_day_medina_12","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"我不是想说我好累，但不管是谁都需要休息。我就收下那瓶西拉鲁水吧。","en":"I don't know how tired you are, but everyone needs a break from time to time. I'll have some of that Siral water.","ja":"疲れた、などということはないが誰しも休息は必要だなそのシラル水は受け取ってやろう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_medina_13#originalText","id":"talk.vc.home_day_medina_13","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"对我来说安息日根本不存在。就算禁止练习，能在自己房间里做的事还有很多。","en":"There's no day of rest for me. Even if all of my training was to get banned, there's still so many things I could do in my room.","ja":"私に安息日などないたとえ稽古が禁止されても自室で出来ることは数多くある"},"kind":"dialogue"},{"uid":"talk.vc.home_day_medina_14#originalText","id":"talk.vc.home_day_medina_14","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"给自己加油。明天学院生活又要开始了。","en":"I need to get myself motivated. Because the academy is going to be starting up again as of tomorrow.","ja":"己に喝を入れているまた明日から、学院生活が始まるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_nergius_integrator_11#originalText","id":"talk.vc.home_day_nergius_integrator_11","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"安息日结束了，代表剑士大人，今天起又要再麻烦你了。","en":"The Day of Rest is over. Swordsman Delegate, I ask that you get back to your duties.","ja":"安息日は終わりました代表剣士殿、今日からまたしっかりとお願いいたします"},"kind":"dialogue"},{"uid":"talk.vc.home_day_nergius_integrator_12#originalText","id":"talk.vc.home_day_nergius_integrator_12","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"为什么你就这么坐不住！？你应该确实履行自己的职务才对！","en":"Why are you so fidgety?! You must take your duties seriously!","ja":"なぜ、そう腰が落ち着かないのですか!?きちんと職務を全うすべきです!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_nergius_integrator_13#originalText","id":"talk.vc.home_day_nergius_integrator_13","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"像这样看着人民欢笑，就会更加巩固我们必须守护和平的决心。","en":"Seeing the peasants with smiles on their faces reinvigorates my sense of duty to protect them.","ja":"こうして楽しむ民を見ると我らが守らねばという決意が新たになります"},"kind":"dialogue"},{"uid":"talk.vc.home_day_nergius_integrator_14#originalText","id":"talk.vc.home_day_nergius_integrator_14","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"这么晚才回来啊？……也罢，有回来就该夸奖你了。","en":"Why are you returning so late? Well, I suppose I should commend you on returning at all.","ja":"こんな時間にお帰りですか……まあ、帰ってきたことを褒めておきましょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_phillia_11#originalText","id":"talk.vc.home_day_phillia_11","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"星期一，一定要加油的心情太强，反而会变得很累呢。","en":"I have this strong feeling that I need to try my best since it's monday. But on the contrary, it's exhausting.","ja":"月曜日って、頑張らなきゃって思いが強すぎて、かえって疲れちゃうよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_phillia_12#originalText","id":"talk.vc.home_day_phillia_12","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"我只要跟大家在一起的话，每天都很开心喔！……不过还是等不及周末的到来啊！","en":"It would be fun if I could be with everyone, everyday... I can't wait for the weekend.","ja":"わたしは、みんなと居られたら毎日楽しいけど……やっぱり週末は待ち遠しいかな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_phillia_13#originalText","id":"talk.vc.home_day_phillia_13","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"可以不用担心明天的事尽情玩乐，其实是件很幸福的事呢。","en":"Not having to worry about tomorrow and just playing along is such a wonderful thing.","ja":"明日のことを心配しないで遊んでいられるってすごく幸せなことだよねー"},"kind":"dialogue"},{"uid":"talk.vc.home_day_phillia_14#originalText","id":"talk.vc.home_day_phillia_14","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"今天好开心喔－－希望下周也像今天一样，是个开心的好日子。","en":"Today was so much fun! I hope that next week will be just as fun as today.","ja":"今日は楽しかったなーまた来週も、今日みたいに楽しい日になりますように"},"kind":"dialogue"},{"uid":"talk.vc.home_day_premiere_11#originalText","id":"talk.vc.home_day_premiere_11","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"星期一的大家多少都有点累呢。明明是一周的开始，但为什么会累呢……","en":"I guess monday is tiring for anyone regardless of the person. Even though it's the start of the week, I wonder why we would be tired...","ja":"月曜日は、みなさんどことなく疲れていますね。週の始まりなのに疲れているのはなぜでしょう……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_premiere_12#originalText","id":"talk.vc.home_day_premiere_12","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"因为周末可以和大家一起聊天，所以我好期待喔！","en":"I'm looking forward to the weekend since I'll be able to talk to everyone again.","ja":"週末になると、みなさんと一緒にお話しできるのでとても楽しみです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_premiere_13#originalText","id":"talk.vc.home_day_premiere_13","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"可以再见到大家……见到你，我很开心。想要跟你多聊聊。","en":"Being able to meet everyone... to meet you, makes me so happy. Let's talk a lot.","ja":"またみなさんに……あなたに会えて、うれしいですたくさんお話ししてください"},"kind":"dialogue"},{"uid":"talk.vc.home_day_premiere_14#originalText","id":"talk.vc.home_day_premiere_14","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"周末要结束了。我明白了。这就是名为寂寞的感情……","en":"Too bad the weekend is over, huh. So that's what they mean when they say they feel lonely...","ja":"週末が終わってしまうんですねこれが寂しい、という感情なのはわかりました……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_rain_11#originalText","id":"talk.vc.home_day_rain_11","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"我喜欢星期一喔！新的一周的起点，不觉得让人心情很好吗？","en":"I love mondays. It's the start of a new week. Isn't that a great feeling?","ja":"わたしは、月曜日って好きだよ新しい週の始まりって気持ちいいじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_day_rain_12#originalText","id":"talk.vc.home_day_rain_12","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"会感受到积劳的时间点大概是过了这周的一半左右吧……不行，我得振作点！","en":"Days worth of fatigue really do pile up during the middle of the week, eh... No, I have to keep pushing forward!","ja":"日々の疲れがたまるのって週の半ばだよね……ダメ、シャキッとしないと!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_rain_13#originalText","id":"talk.vc.home_day_rain_13","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"嗯－－，今天得稍微休息一下，消除疲劳才行。","en":"Yes, I'll be taking a break today. I need to get some rest.","ja":"うーん、今日は少し休憩疲れを取らないと"},"kind":"dialogue"},{"uid":"talk.vc.home_day_rain_14#originalText","id":"talk.vc.home_day_rain_14","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"有好好休息过了。明天又可以继续加油了！","en":"I got plenty of rest, so I should be able to do my best from tomorrow onwards!","ja":"しっかり休めたし明日からまた頑張れるね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_renri_11#originalText","id":"talk.vc.home_day_renri_11","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"安息日之后的那一天，早上起来的时候果然还是有点难呀。","en":"It's going to be a little difficult waking up on the next day of rest.","ja":"安息日の次の日は、やっぱり少し起きるのが大変だよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_renri_12#originalText","id":"talk.vc.home_day_renri_12","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"下次的安息日感觉好远呀。虽然一想到可以和你一起外出，我就觉得很开心……","en":"Can't wait for the next day of rest. It would be great to go somewhere with you again...","ja":"次の安息日が待ち遠しいねまた、君とどこかに出かけられると嬉しいんだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_renri_13#originalText","id":"talk.vc.home_day_renri_13","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"今天是安息日，你有什么事吗？我、我……我是没事啦……","en":"Do you have any plans for today's day of rest? I... I'm free, so...","ja":"今日の安息日、予定はあるの?ぼ、僕は……ないんだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_renri_14#originalText","id":"talk.vc.home_day_renri_14","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"明天再继续努力工作吧。为了迎接开心快乐的安息日。","en":"We'll have to train hard again, starting tomorrow. In order to have a fun day of rest.","ja":"また明日からしっかり働かないとね楽しい安息日が迎えられるように"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_11#originalText","id":"talk.vc.home_day_ronye_11","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天开始，要再致力于课业！","en":"Starting today, it's back to working hard on my studies and my training!","ja":"今日からまた、ちゃんと課題と授業をがんばります! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_12#originalText","id":"talk.vc.home_day_ronye_12","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"虽然作业很多，但是剑的修练却很有趣。","en":"My schoolwork is stressful, but I enjoy my sword training.","ja":"課題は大変ですけどでも剣の修業は楽しいです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_13#originalText","id":"talk.vc.home_day_ronye_13","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，您要怎么度过安息日呢？","en":"Sir, how are you going to spend your day of rest?","ja":"先輩は、安息日はなにをして過ごされるんですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_day_ronye_14#originalText","id":"talk.vc.home_day_ronye_14","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"今天玩过头，觉得有些累了……但是很开心。","en":"I'm a little tired from overexerting myself, but I had a lot of fun!","ja":"今日は遊びすぎて少し疲れちゃいましたが……でも楽しかったです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sachi_11#originalText","id":"talk.vc.home_day_sachi_11","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"总觉得一直待在虚拟世界，就会对日子越来越无感呢。","en":"When you're in the virtual world long enough, you lose track of what day it is.","ja":"なんだか、ずっと仮想世界にいると曜日の感覚ってなくなっちゃうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sachi_12#originalText","id":"talk.vc.home_day_sachi_12","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"好怀念和平的日常生活……希望总有一天，那种日子可以到来。","en":"Oh, I miss my peaceful life before this... I hope I can get my old life back someday.","ja":"平和な日常が懐かしい……いつか、そんな日がまた来るといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sachi_13#originalText","id":"talk.vc.home_day_sachi_13","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"今天是假日，我想要快乐地度过呢。","en":"Since we have the day off, I want to do something fun.","ja":"お休みだから、今日は楽しく過ごしたいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sachi_14#originalText","id":"talk.vc.home_day_sachi_14","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"虽然晚上我总是会感到不安……不过我今天玩得很开心，所以应该能怀着这份回忆入睡。","en":"I always feel uneasy at night... But since I had such a great day, I might be able to sleep easily tonight.","ja":"夜はいつも不安だけど……今日は楽しかったからその思い出で眠れるかも"},"kind":"dialogue"},{"uid":"talk.vc.home_day_scheta_11#originalText","id":"talk.vc.home_day_scheta_11","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"今天起，又是一星期的开始。大家都好像很慌乱呢。","en":"Looks like today will mark the beginning of another week. Since everyone seems to be so busy.","ja":"今日からまた、1週間が始まるのねみんな、慌ただしそうだから"},"kind":"dialogue"},{"uid":"talk.vc.home_day_scheta_12#originalText","id":"talk.vc.home_day_scheta_12","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我很喜欢从远处观望人们正在工作的样子。","en":"I look observing from afar to check if people are doing their jobs.","ja":"人々が仕事をしているのを遠くから眺めるのは、好き"},"kind":"dialogue"},{"uid":"talk.vc.home_day_scheta_13#originalText","id":"talk.vc.home_day_scheta_13","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"安息日……跟集成骑士没什么关系……","en":"Day of rest... That doesn't really apply to Integrity Knights.","ja":"安息日……整合騎士には、あんまり関係ない……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_scheta_14#originalText","id":"talk.vc.home_day_scheta_14","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"安息日结束，明天再见、吧。","en":"The day of rest has ended.  See you tomorrow, then.","ja":"安息日は終わりまた明日、ね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_selka_11#originalText","id":"talk.vc.home_day_selka_11","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"今天开始又得好好加油才行。到下一次安息日之前，我想要学会一种神圣术。","en":"It's back to the grind today. I'd like to learn another Sacred Art by the next day of rest.","ja":"今日からまた頑張らないとね次の安息日までに、神聖術をひとつは覚えたいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_selka_12#originalText","id":"talk.vc.home_day_selka_12","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"照顾小孩很有趣。嗯，不过也是有点累人啦……","en":"I enjoy looking after the children. Though it can be a stressful job sometimes.","ja":"子どもたちのお世話は楽しいわまあ、ちょっとは大変だけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_selka_13#originalText","id":"talk.vc.home_day_selka_13","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"大家一起在安息日出去玩吧。我会做很多便当的。","en":"Let's all go out on the next day of rest. I'll make us a big picnic lunch.","ja":"安息日にはみんなで出かけましょうお弁当いっぱい作るからね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_selka_14#originalText","id":"talk.vc.home_day_selka_14","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"今天又平安地过去了，得感谢史提西亚大人才行。","en":"I need to thank the Goddess Stacia for everything I've accomplished today.","ja":"今日も一日、無事に終わったことをステイシア様に感謝しないと"},"kind":"dialogue"},{"uid":"talk.vc.home_day_seven_11#originalText","id":"talk.vc.home_day_seven_11","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"对研究者而言，不管是星期一还是星期二都没什么关系。虽然会觉得旁边的人都很忙啦。","en":"It doesn't matter weather it is monday or tuesday. To a researcher, they're busy any day of the week.","ja":"研究者には、月曜も火曜もあんまり関係ないわね周りが忙しそうだなーとは思うけど"},"kind":"dialogue"},{"uid":"talk.vc.home_day_seven_12#originalText","id":"talk.vc.home_day_seven_12","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"这周状况很好呢。照这个样子，到周末以前感觉可以告一段落。","en":"I feel pretty good this week. Until the weekend comes, looks like it will calm down a bit.","ja":"今週はなかなか調子がいいわこれなら、週末までにはいち段落つきそう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_seven_13#originalText","id":"talk.vc.home_day_seven_13","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"研究者也需要休息啊。所以周末我会像这样，做些自己想做的事。","en":"Researchers need their breaks. That way, they can spread their wings on the weekend.","ja":"研究者にだって休息は必要よだからこうして週末は羽を伸ばすの"},"kind":"dialogue"},{"uid":"talk.vc.home_day_seven_14#originalText","id":"talk.vc.home_day_seven_14","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"……明天开始，又可以一起加油了……晚安……","en":"...Again, let's try our best from tomorrow... Good night...","ja":"……また、明日から一緒に頑張りましょ……おやすみなさい……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_shasta_11#originalText","id":"talk.vc.home_day_shasta_11","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"一周的开始大家看起来都很辛苦。看来需要加把劲才行啊。","en":"Looks like the beginning of the week is tough for everyone. I think a little effort is going to be needed here.","ja":"週の初めは、みな辛そうだな少し気合いを入れてやる必要がありそうだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_shasta_12#originalText","id":"talk.vc.home_day_shasta_12","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"你属下的骑士们怎么样？大家的士气都很高吗？","en":"How are the men doing? Is morale high?","ja":"配下の騎士達はどうだ?みなの士気は高いか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_shasta_13#originalText","id":"talk.vc.home_day_shasta_13","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"安息日？要是那种没有结果的战争消失，那样的日子大概就会到来吧。","en":"Day of rest? When there's no more barren struggles, I would be open to that kind of day.","ja":"安息日?不毛な争いが無くなればそのような日も訪れるだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_shasta_14#originalText","id":"talk.vc.home_day_shasta_14","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"明天又要再麻烦你了。我很感谢你。","en":"I'm counting on you tomorrow. I thank you for your service.","ja":"また明日から苦労をかけるお前には、感謝しているんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_11#originalText","id":"talk.vc.home_day_silica_11","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"今天开始又是平日了呢。……一起加油吧！","en":"It’s the start of a new week... Let's push through!","ja":"今日からまた平日ですね……がんばりましょう! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_12#originalText","id":"talk.vc.home_day_silica_12","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"一想到周末，我就会稍微打起精神。","en":"Thinking about the weekend always gives me energy.","ja":"週末のことを考えるとちょっと元気が出ます"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_13#originalText","id":"talk.vc.home_day_silica_13","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"趁着今天是假日，要好好消除疲劳喔。","en":"Since we have the day off, let's really use it to relax.","ja":"今日はお休みだからちゃんと疲れを取りましょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_silica_14#originalText","id":"talk.vc.home_day_silica_14","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"假日的时候我们相处这么久，感觉下礼拜也能努力了。","en":"Since I got to spend so much time with you this weekend, I have plenty of energy to face the week.","ja":"お休み、たくさん一緒だったので来週もがんばれそうです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_11#originalText","id":"talk.vc.home_day_sinon_11","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"又是新的一个礼拜呢。这周也要在不勉强的范围内，好好加油。","en":"It's the start of a whole new week. Hope you have a good one.","ja":"新しい1週間の始まりね今週も、無理しないで頑張って"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_12#originalText","id":"talk.vc.home_day_sinon_12","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽然学校那边有点不好受，但已经不要紧了。再说，多少还是有些开心的事情嘛。","en":"School is pretty tough for me, but I'm okay now. Sometimes I have fun, too.","ja":"学校はちょっと大変だけどもう平気。楽しいことも少しはあるしね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_13#originalText","id":"talk.vc.home_day_sinon_13","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你假日有安排了吗？没有的话，就稍微陪陪我吧。","en":"Do you have any plans this weekend? If not, wanna go somewhere with me?","ja":"休日の予定は? ないんだったら、私にちょっと付き合ってよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sinon_14#originalText","id":"talk.vc.home_day_sinon_14","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"真是愉快的假日呢。让我们一起期待下礼拜的这一天，借此努力一整周吧。","en":"What a great weekend. I'll make it through next week okay, knowing I'll have another fun weekend to look forward to.","ja":"楽しい休日だったわまた1週間頑張りましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_11#originalText","id":"talk.vc.home_day_sortiliena_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天起要再请你多指教。下次比试，就着重在训练体术吧。","en":"I'm expecting good things from you again today. We're focusing on martial arts today.","ja":"今日からまたよろしく頼む今度は、体術を中心に立ち合おうか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_12#originalText","id":"talk.vc.home_day_sortiliena_12","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"因为每天都能像这样见到你，我很开心喔。","en":"All my days are filled with fun, now that I get to spend them with you.","ja":"こうして毎日お前と会えるから私は楽しいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_13#originalText","id":"talk.vc.home_day_sortiliena_13","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"安息日的时候，我想上街购物。你方便的话要不要一起去？","en":"For the day of rest, I was thinking of going shopping. Would you like to come with me?","ja":"安息日は、街に買い物に行こうと思うんだよかったら、一緒に行くか? "},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_14#originalText","id":"talk.vc.home_day_sortiliena_14","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"真是充实的安息日。这样一来，我明天开始又能继续前进了。","en":"What a fulfilling day of rest that was. Now I'm recharged for the rest of the week.","ja":"充実した安息日だったこれでまた、明日から前に進める"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_child_11#originalText","id":"talk.vc.home_day_sortiliena_child_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"来，今天起也要继续修行剑技。","en":"Okay. Back to sword training today.","ja":"さあ、今日からまた剣の修業だ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_child_12#originalText","id":"talk.vc.home_day_sortiliena_child_12","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"每天持续训练是很重要的。","en":"It's crucial to never skip a day of training.","ja":"稽古は毎日欠かさずやるのが大切だぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_child_13#originalText","id":"talk.vc.home_day_sortiliena_child_13","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"安息日啊……休息的确也很重要。","en":"A day of rest... Yes. Taking time off is also important.","ja":"安息日か……確かに、休憩も時大事だな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_sortiliena_child_14#originalText","id":"talk.vc.home_day_sortiliena_child_14","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"今天有充分休息了，所以明天开始要继续好好努力。","en":"I rested up well today, which means I have to get back to training that much harder tomorrow.","ja":"今日はしっかり休めたからまた明日から頑張らないと"},"kind":"dialogue"},{"uid":"talk.vc.home_day_strea_11#originalText","id":"talk.vc.home_day_strea_11","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"我不太懂星期是什么感觉……但是大家今天好像都很辛苦？","en":"I don't really have a sense for days...but everyone seems to be a little tired today?","ja":"アタシには、曜日の感覚ってあんまりわかんないけど……今日はみんな大変そうだね?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_strea_12#originalText","id":"talk.vc.home_day_strea_12","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"一到周末，大家都会跟我玩……但是现在大家好像很忙，总觉得有点寂寞。","en":"It used to be that when it was the weekend everyone would play together...but it seems like everyone is busy. How sad.","ja":"週末になったら、みんな遊んでくれるけど……今は忙しそうでなんだか寂しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_strea_13#originalText","id":"talk.vc.home_day_strea_13","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"大家今天看起来都好开心喔！如果每天都是周末就好了。","en":"Looks like everyone is having fun today! If everyday was the weekend, that would be amazing.","ja":"今日はみんな楽しそうだね!毎日が週末だったらいいのに"},"kind":"dialogue"},{"uid":"talk.vc.home_day_strea_14#originalText","id":"talk.vc.home_day_strea_14","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"我还玩不够啊。但是……真拿你没办法，今天就先玩到这里吧！","en":"I still haven't played enough...but that can't be helped. I guess I'll leave things like that for today!","ja":"アタシは、まだまだ遊び足りないけど……しょうがない今日はこのくらいにしてやるか!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_subtilizer_11#originalText","id":"talk.vc.home_day_subtilizer_11","speaker":{"ja":"サトライザー"},"text":{"ja":"矮小な魂どもがせこせこと働き始める日か……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_subtilizer_12#originalText","id":"talk.vc.home_day_subtilizer_12","speaker":{"ja":"サトライザー"},"text":{"ja":"あんなにあくせく働いて奴らの魂はすり減らないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_subtilizer_13#originalText","id":"talk.vc.home_day_subtilizer_13","speaker":{"ja":"サトライザー"},"text":{"ja":"安堵している魂、か面白みに欠けるな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_subtilizer_14#originalText","id":"talk.vc.home_day_subtilizer_14","speaker":{"ja":"サトライザー"},"text":{"ja":"次こそ、もっと輝ける魂を見つけたいものだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_11#originalText","id":"talk.vc.home_day_suguha_11","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"虽然星期一总是让人觉得辛苦，但心情忧郁就会更难过，所以我才决定要打起精神！","en":"Mondays suck, but complaining only makes it worse. So, I always try to stay positive!","ja":"月曜日は大変だけど憂鬱だって思うと余計辛いから元気出すことにしてるの! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_12#originalText","id":"talk.vc.home_day_suguha_12","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我已经习惯晨练了。尝试后反而会觉得很有趣喔！","en":"I'm used to morning practice by now. Wanna try it? It's actually kinda fun.","ja":"朝練は、もう慣れちゃったからやってみると、案外楽しいよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_13#originalText","id":"talk.vc.home_day_suguha_13","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"难得放假，我想跟你一起度过。","en":"Since we have some time off for once, I'd like to spend it together.","ja":"せっかくのお休みだし一緒に過ごしたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_suguha_14#originalText","id":"talk.vc.home_day_suguha_14","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"假期结束了。快乐的时间总是过得特别快呢。","en":"Vacation is over already? Man, time does fly when you're having fun!","ja":"お休み終わっちゃった楽しい時間は、あっという間だね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_11#originalText","id":"talk.vc.home_day_tiese_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天开始，又要受学长照顾了。请多多指教啰。","en":"This starts another week of me tending to your every need. It's an honor to serve.","ja":"今日から、また先輩のお世話をいたしますよろしくお願いいたしますね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_12#originalText","id":"talk.vc.home_day_tiese_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"训练后跟学长一起度过的时光，是最快乐的。","en":"Time spent with you after training is my favorite time.","ja":"教練後の、先輩と一緒の時間が、一番楽しいです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_13#originalText","id":"talk.vc.home_day_tiese_13","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天我打算跟芙蕾妮卡她们一起去购物。","en":"I'm thinking of going shopping today with my roommates.","ja":"今日はフレニーカたちと買い物に行こうと思ってるんです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_14#originalText","id":"talk.vc.home_day_tiese_14","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"如果下一个安息日有幸能跟学长一起出门，那就太幸福了。","en":"I would be so honored if we could go out together on our next day of rest.","ja":"次の安息日には、先輩と一緒にお出かけできたらとても幸せです"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_child_11#originalText","id":"talk.vc.home_day_tiese_child_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天开始也要像个贵族一样继续努力！","en":"We need to give it our all starting today! Like a noble!","ja":"今日からまた頑張らないと貴族らしく!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_child_12#originalText","id":"talk.vc.home_day_tiese_child_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"唔唔，神圣语真难。一定要在明天之前背好……","en":"The Sacred Tongue is so difficult. I need to remember these by tomorrow...","ja":"うう、神聖語は難しいなあ明日までに覚えないと……"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_child_13#originalText","id":"talk.vc.home_day_tiese_child_13","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"因为今天是安息日，所以不用训练。呵呵，好开心啊。","en":"There's no training today since it's a day off. Hehe. What a relief.","ja":"安息日だから、今日は稽古はお休みですふふ、うれしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_tiese_child_14#originalText","id":"talk.vc.home_day_tiese_child_14","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好好休息过了，明天开始又可以继续努力！","en":"I got plenty of rest, so I'll be able to do my best starting from tomorrow!","ja":"ゆっくり休めたから明日からまた頑張れそうです!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vassago_11#originalText","id":"talk.vc.home_day_vassago_11","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"星期一？今天星期几对我来说一点都不重要。","en":"Monday? I honestly do not care what today is or what day it is in general.","ja":"月曜?今日が何曜日だろうが俺にはどうでもいい話だな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vassago_12#originalText","id":"talk.vc.home_day_vassago_12","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"每天都奔波劳碌真是辛苦你了。","en":"Don't work so hard everyday.","ja":"毎日せこせこご苦労さんってな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vassago_13#originalText","id":"talk.vc.home_day_vassago_13","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"周末？跟我无关。","en":"Weekend? That has nothing to do with me.","ja":"週末?俺には関係のない話だな"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vassago_14#originalText","id":"talk.vc.home_day_vassago_14","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"你还能活到明天真好啊？","en":"Isn't it great that we still have tomorrow to look forward to?","ja":"また明日があってよかったなぁ?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vector_11#originalText","id":"talk.vc.home_day_vector_11","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"矮小的灵魂们又慌忙地开始工作了吗……","en":"I guess this is the day in which tiny souls go out to work..."},"kind":"dialogue"},{"uid":"talk.vc.home_day_vector_12#originalText","id":"talk.vc.home_day_vector_12","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"那么忙碌地工作他们的灵魂都不会被削弱吗？","en":"Do their souls wear out by working that hard?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vector_13#originalText","id":"talk.vc.home_day_vector_13","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"安稳的灵魂吗。那就不有趣了。","en":"A peaceful soul? Where is the fun in that?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_vector_14#originalText","id":"talk.vc.home_day_vector_14","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"希望下一次，可以找到更加光辉闪烁的灵魂……","en":"Next time, I want to find a brighter spirit... Next time for sure..."},"kind":"dialogue"},{"uid":"talk.vc.home_day_yui_11#originalText","id":"talk.vc.home_day_yui_11","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"周末还是结束了呢。今天开始一起加油吧！","en":"Too bad the weekend is over. But, I wish you well this week!","ja":"週末が終わっちゃいましたね今日から頑張りましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yui_12#originalText","id":"talk.vc.home_day_yui_12","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸不累吗？累的话就不要勉强，休息一下吧。","en":"Aren't you tired? If you are, go ahead and take a nap.","ja":"疲れてないですか?疲れたら無理せず、休んでください"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yui_13#originalText","id":"talk.vc.home_day_yui_13","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"假日要跟妈妈出门吗？","en":"Are you going out with Mom on your day off?","ja":"お休みはママとお出かけですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yui_14#originalText","id":"talk.vc.home_day_yui_14","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"今天玩得好开心！嘿嘿……下次还要带我出门喔。","en":"Today was so much fun! Hehe, I'd love it if you took me out again.","ja":"今日は楽しかったです!えへへ……また私もお出かけに連れて行ってください"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuna_11#originalText","id":"talk.vc.home_day_yuna_11","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"星期一到了！如果这星期也有很多有趣的事就好了！","en":"It's monday! I hope that there will be a lot of interesting things this week too!","ja":"月曜日だね!今週も面白いことがたくさんあるといいなあ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuna_12#originalText","id":"talk.vc.home_day_yuna_12","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"到了周末就可以一起玩了，对吧？嗯－－，快等不及了啦～","en":"We can play when it's the weekend, right? I can't wait...","ja":"週末になったら一緒に遊べるんだよね?うーん、待ち遠しいよー"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuna_13#originalText","id":"talk.vc.home_day_yuna_13","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"周末终于到了！来，我们一起出门吧！地点是……出了门再来想吧！","en":"It's finally the weekend! Let's hangout! As for where... let's decide when we hangout!","ja":"やっと週末だね!さあ、一緒に出かけるよー!行く先は……出かけてから考える!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuna_14#originalText","id":"talk.vc.home_day_yuna_14","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"……今天很开心喔。一直以来谢谢你。","en":"...Today was really fun. Thank you, as always.","ja":"……今日は楽しかったいつもありがとうね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_11#originalText","id":"talk.vc.home_day_yuuki_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我不讨厌星期一。会有种鼓足干劲，一整个礼拜都要加油的感觉。","en":"I don't mind Mondays. I always feel pumped to make it a good week!","ja":"月曜日って、キライじゃないんだ一週間頑張ろうって、気合が入る感じ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_12#originalText","id":"talk.vc.home_day_yuuki_12","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"每天都能像这样见到你，我真的很开心。","en":"I love being able to see you every day like this.","ja":"毎日こうやってキミに会えるのはとってもうれしいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_13#originalText","id":"talk.vc.home_day_yuuki_13","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"今天放假，所以我们从早上就能在一起了呢！","en":"Since we have the day off, that means we can see each other from dawn 'til dusk!","ja":"今日はお休みだから朝からずっと一緒にいられるね! "},"kind":"dialogue"},{"uid":"talk.vc.home_day_yuuki_14#originalText","id":"talk.vc.home_day_yuuki_14","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"这礼拜也就这样结束了呢，时间过得真快耶。","en":"Another week in the books. Time sure flies!","ja":"今週も終わっちゃったねあっという間だったなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_administrator_1#originalText","id":"talk.vc.home_etc_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"有劳你了，我已经准备好奖赏。","en":"Well done. I have a reward for you.","ja":"ご苦労様だったわね褒美を用意してあるわ"},"kind":"dialogue"}]};
